import java.util.*;
import java.io.*;

public class Variant5 {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String[] parts = br.readLine().split(" ");
        int N = Integer.parseInt(parts[0]);
        long lmao = Long.parseLong(parts[1]);
        if (lmao >= N) {
            System.out.println(0);
        } else {
            int K = (int) lmao;
            int C = N - K;
            long[] factorials = new long[200001];
            long[] invFactorials = new long[200001];
            factorials[0] = 1;
            invFactorials[0] = 1;
            for (int i = 1; i <= 200000; i++) {
                factorials[i] = (factorials[i - 1] * i) % 998244353L;
                invFactorials[i] = modInverse(factorials[i], 998244353L);
            }
            long result = modPow(C, N, 998244353L);
            for (int e = 1; e < C; e++) {
                long temp = modPow(C - e, N, 998244353L);
                temp = (temp * nCr(e, C, factorials, invFactorials)) % 998244353L;
                if (e % 2 == 1)
                    result = (result - temp + 998244353L) % 998244353L;
                else
                    result = (result + temp) % 998244353L;
            }
            result = (result * nCr(C, N, factorials, invFactorials)) % 998244353L;
            if (K > 0)
                result = (2 * result) % 998244353L;
            System.out.println(result);
        }
    }

    static long nCr(int a, int b, long[] fact, long[] invFact) {
        return (((fact[b] * invFact[a]) % 998244353L) * invFact[b - a]) % 998244353L;
    }

    static long modInverse(long a, long m) {
        return power(a, m - 2, m);
    }

    static long power(long base, long exp, long mod) {
        long res = 1;
        base %= mod;
        while (exp > 0) {
            if ((exp & 1) == 1)
                res = (res * base) % mod;
            base = (base * base) % mod;
            exp >>= 1;
        }
        return res;
    }
}
